package im.nexar.jarvis;

import android.content.*;
import android.media.AudioManager;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.cert.X509Certificate;
import java.util.*;
import javax.net.ssl.*;
import org.json.*;

public final class DesktopApi {
  static final String DEFAULT_VOICE="de-DE-ConradNeural", DEFAULT_CITY="Wien";
  final Context c; final SharedPreferences p; Timer timer; String cloudUrl, anonKey;
  DesktopApi(Context c, SharedPreferences p){this.c=c;this.p=p;loadCloud();}
  private void loadCloud(){try(InputStream in=c.getAssets().open("cloud.json")){JSONObject j=new JSONObject(read(in));cloudUrl=j.optString("url").replaceAll("/$","");anonKey=j.optString("anonKey");}catch(Exception e){cloudUrl="";anonKey="";}}
  private static String read(InputStream in)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] z=new byte[8192];int n;while((n=in.read(z))!=-1)b.write(z,0,n);return b.toString("UTF-8");}
  static final class R{final int code;final String body;R(int c,String b){code=c;body=b;}}
  static final class Voice {final String shortName,locale,gender,friendlyName; Voice(String s,String l,String g,String f){shortName=s;locale=l;gender=g;friendlyName=f;} String label(){return friendlyName+" · "+locale+" · "+gender;}}
  static final class SpeakResult {final byte[] audio;final String mime;SpeakResult(byte[] a,String m){audio=a;mime=m;}}
  interface VoiceCallback {void done(List<Voice> voices,String error);}
  interface SpeakCallback {void done(SpeakResult result,String error);}
  interface MediaCallback {void done(String error);}
  private R http(String method,String raw,String body,Map<String,String> headers,SSLSocketFactory ssl,HostnameVerifier hv){try{URL u=new URL(raw);if(!"https".equalsIgnoreCase(u.getProtocol()))return new R(0,"HTTPS erforderlich");HttpsURLConnection x=(HttpsURLConnection)u.openConnection();if(ssl!=null)x.setSSLSocketFactory(ssl);if(hv!=null)x.setHostnameVerifier(hv);x.setRequestMethod(method);x.setConnectTimeout(9000);x.setReadTimeout(9000);x.setRequestProperty("Accept","application/json");if(headers!=null)for(Map.Entry<String,String>e:headers.entrySet())x.setRequestProperty(e.getKey(),e.getValue());if(body!=null){x.setDoOutput(true);x.setRequestProperty("Content-Type","application/json");try(OutputStream o=x.getOutputStream()){o.write(body.getBytes(StandardCharsets.UTF_8));}}int code=x.getResponseCode();InputStream in=code<400?x.getInputStream():x.getErrorStream();return new R(code,in==null?"":read(in));}catch(Exception e){return new R(0,e.getClass().getSimpleName());}}
  private R desktop(String method,String path,String body){try{String base=p.getString("baseUrl","");URL u=new URL(base);String fp=p.getString("fingerprint","").replace(":","").toLowerCase(Locale.US);if(!"https".equalsIgnoreCase(u.getProtocol())||fp.length()!=64)return new R(0,"Desktop-Pin ungültig");final String host=u.getHost();TrustManager[]tm={new X509TrustManager(){final X509TrustManager d=defaultTm();public X509Certificate[]getAcceptedIssuers(){return d.getAcceptedIssuers();}public void checkClientTrusted(X509Certificate[]a,String b)throws java.security.cert.CertificateException{d.checkClientTrusted(a,b);}public void checkServerTrusted(X509Certificate[]a,String b)throws java.security.cert.CertificateException{if(a==null||a.length==0)throw new java.security.cert.CertificateException("Kein Zertifikat");try{byte[]dig=MessageDigest.getInstance("SHA-256").digest(a[0].getEncoded());if(!MessageDigest.isEqual(dig,hex(fp)))throw new java.security.cert.CertificateException("Zertifikat-Pin stimmt nicht");}catch(java.security.cert.CertificateException e){throw e;}catch(Exception e){throw new java.security.cert.CertificateException(e);}}}};SSLContext sc=SSLContext.getInstance("TLS");sc.init(null,tm,new SecureRandom());Map<String,String>h=new HashMap<>();h.put("Authorization","Bearer "+p.getString("token",""));return http(method,new URL(u,path).toString(),body,h,sc.getSocketFactory(),(hname,s)->host.equalsIgnoreCase(hname));}catch(Exception e){return new R(0,"Desktop-Verbindung fehlgeschlagen");}}
  private static X509TrustManager defaultTm(){try{TrustManagerFactory f=TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());f.init((KeyStore)null);for(TrustManager t:f.getTrustManagers())if(t instanceof X509TrustManager)return(X509TrustManager)t;}catch(Exception e){}throw new IllegalStateException();}
  private static byte[]hex(String s){byte[]b=new byte[s.length()/2];for(int i=0;i<b.length;i++)b[i]=(byte)Integer.parseInt(s.substring(i*2,i*2+2),16);return b;}
  boolean isPaired(){return !p.getString("baseUrl","").isEmpty()&&!p.getString("token","").isEmpty();}
  String pair(String invite){try{JSONObject j=new JSONObject(new String(Base64.getUrlDecoder().decode(invite.trim()),StandardCharsets.UTF_8));String url=j.getString("url"),fp=j.getString("fingerprint").replace(":","");if(!url.startsWith("https://")||fp.length()!=64)return"Abgelehnt: HTTPS und SHA-256-Pin erforderlich";p.edit().putString("baseUrl",url.replaceAll("/$","")).putString("fingerprint",fp).apply();R r=desktop("POST","/pair",new JSONObject().put("secret",j.getString("secret")).put("name","Jarvis Android").toString());if(r.code<200||r.code>=300)throw new Exception();JSONObject x=new JSONObject(r.body);p.edit().putString("token",x.getString("token")).putString("deviceId",x.optString("deviceId")).apply();return"Desktop verbunden";}catch(Exception e){p.edit().remove("baseUrl").remove("fingerprint").remove("token").apply();return"Einladung ungültig oder Kopplung fehlgeschlagen";}}
  private String json(String k,String v){try{return new JSONObject().put(k,v).toString();}catch(Exception e){return"{}";}}
  void media(String a){media(a,null);}
  void media(String a,MediaCallback cb){if(isPaired()){new Thread(()->{R r=desktop("POST","/media",json("action",a));if(cb!=null)cb.done(r.code>=200&&r.code<300?null:error(r));}).start();return;}AudioManager m=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);if("volumeup".equals(a))m.adjustStreamVolume(AudioManager.STREAM_MUSIC,AudioManager.ADJUST_RAISE,AudioManager.FLAG_SHOW_UI);else if("volumedown".equals(a))m.adjustStreamVolume(AudioManager.STREAM_MUSIC,AudioManager.ADJUST_LOWER,AudioManager.FLAG_SHOW_UI);else if("mute".equals(a))m.adjustStreamVolume(AudioManager.STREAM_MUSIC,AudioManager.ADJUST_TOGGLE_MUTE,AudioManager.FLAG_SHOW_UI);else{int k="next".equals(a)?87:"previous".equals(a)?88:"stop".equals(a)?86:85;m.dispatchMediaKeyEvent(new android.view.KeyEvent(0,k));m.dispatchMediaKeyEvent(new android.view.KeyEvent(1,k));}if(cb!=null)cb.done(null);}
  void voices(VoiceCallback cb){if(!isPaired()){cb.done(Collections.emptyList(),"Für Microsoft-Stimmen mit PC koppeln");return;}new Thread(()->{R r=desktop("GET","/voices",null);try{if(r.code<200||r.code>=300)throw new Exception(error(r));JSONArray a=new JSONArray(r.body);List<Voice> out=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject j=a.getJSONObject(i);out.add(new Voice(j.getString("ShortName"),j.optString("Locale"),j.optString("Gender"),j.optString("FriendlyName")));}cb.done(out,null);}catch(Exception e){cb.done(Collections.emptyList(),e.getMessage()==null?"Stimmen konnten nicht geladen werden":e.getMessage());}}).start();}
  void speak(String text,String voice,SpeakCallback cb){if(!isPaired()){cb.done(null,"Für Microsoft-Stimmen mit PC koppeln");return;}new Thread(()->{R r=desktop("POST","/speak",json2(text,voice));try{if(r.code<200||r.code>=300)throw new Exception(error(r));JSONObject j=new JSONObject(r.body);cb.done(new SpeakResult(Base64.getDecoder().decode(j.getString("audio")),j.optString("mime","audio/mpeg")),null);}catch(Exception e){cb.done(null,e.getMessage()==null?"Sprachvorschau fehlgeschlagen":e.getMessage());}}).start();}
  private String json2(String text,String voice){try{return new JSONObject().put("text",text).put("voice",voice).toString();}catch(Exception e){return"{}";}}
  String weather(String city){try{String q=URLEncoder.encode(city.trim(),"UTF-8");R g=http("GET","https://geocoding-api.open-meteo.com/v1/search?name="+q+"&count=1&language=de&format=json",null,null,null,null);if(g.code<200||g.code>=300)throw new IOException("Geocoding HTTP "+g.code);JSONArray a=new JSONObject(g.body).optJSONArray("results");if(a==null||a.length()==0)throw new IOException("Ort nicht gefunden");JSONObject place=a.getJSONObject(0);double lat=place.getDouble("latitude"),lon=place.getDouble("longitude");R w=http("GET","https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lon+"&current=temperature_2m,relative_humidity_2m,apparent_temperature,weather_code,wind_speed_10m&timezone=auto",null,null,null,null);if(w.code<200||w.code>=300)throw new IOException("Wetter HTTP "+w.code);JSONObject j=new JSONObject(w.body),cur=j.optJSONObject("current");if(cur==null||!cur.has("temperature_2m"))throw new IOException("Wetterdaten fehlen");return"Wetter · "+place.optString("name",city)+"  "+cur.getDouble("temperature_2m")+" °C · Code "+cur.optInt("weather_code");}catch(Exception e){return"Wetter · "+city+" nicht verfügbar ("+e.getMessage()+")";}}
  void startPolling(Runnable done){stopPolling();timer=new Timer();timer.scheduleAtFixedRate(new TimerTask(){public void run(){syncProfile();if(isPaired()){R r=desktop("GET","/state",null);if(r.code>=200&&r.code<300)applyDesktopState(r.body);}done.run();}},0,15000);}
  void stopPolling(){if(timer!=null){timer.cancel();timer=null;}}
  private void applyDesktopState(String body){try{JSONObject root=new JSONObject(body),s=root.optJSONObject("settings");if(s==null)return;SharedPreferences.Editor e=p.edit();if(s.has("voice"))e.putString("voice",s.getString("voice"));if(s.has("weatherCity"))e.putString("city",s.getString("weatherCity"));if(s.has("alwaysOnTop"))e.putBoolean("alwaysOnTop",s.getBoolean("alwaysOnTop"));if(s.has("wakeEnabled"))e.putBoolean("wakeEnabled",s.getBoolean("wakeEnabled"));e.apply();}catch(Exception ignored){}}
  boolean cloudConfigured(){return cloudUrl.startsWith("https://")&&!anonKey.isEmpty();}
  private Map<String,String> cloudHeaders(boolean auth){Map<String,String>h=new HashMap<>();h.put("apikey",anonKey);String t=p.getString("accessToken","");if(auth&&!t.isEmpty())h.put("Authorization","Bearer "+t);return h;}
  String cloudSignup(String e,String pw){if(!cloudConfigured())return"Cloud-Anmeldung noch nicht konfiguriert";R r=http("POST",cloudUrl+"/auth/v1/signup",json2(e,pw),cloudHeaders(false),null,null);if(r.code>=200&&r.code<300)return"Registrierung erfolgreich. Bitte E-Mail bestätigen, danach anmelden.";return error(r);}
  String cloudLogin(String e,String pw){R r=http("POST",cloudUrl+"/auth/v1/token?grant_type=password",json2(e,pw),cloudHeaders(false),null,null);if(r.code>=200&&r.code<300)try{saveAuth(new JSONObject(r.body));syncProfile();return"Cloud angemeldet";}catch(Exception x){return"Cloud-Antwort ungültig";}return error(r);}
  private void saveAuth(JSONObject j){JSONObject u=j.optJSONObject("user");p.edit().putString("accessToken",j.optString("access_token")).putString("refreshToken",j.optString("refresh_token")).putString("userId",u==null?"":u.optString("id")).putString("email",u==null?"":u.optString("email")).apply();}
  String refresh(){R r=http("POST",cloudUrl+"/auth/v1/token?grant_type=refresh_token",json("refresh_token",p.getString("refreshToken","")),cloudHeaders(false),null,null);if(r.code>=200&&r.code<300)try{saveAuth(new JSONObject(r.body));return"";}catch(Exception e){}return error(r);}
  private R cloud(String method,String url,String body){R r=http(method,url,body,cloudHeaders(true),null,null);if(r.code==401&&!p.getString("refreshToken","").isEmpty()&&refresh().isEmpty())r=http(method,url,body,cloudHeaders(true),null,null);return r;}
  String cloudLogout(){if(!p.getString("accessToken","").isEmpty())http("POST",cloudUrl+"/auth/v1/logout",null,cloudHeaders(true),null,null);p.edit().remove("accessToken").remove("refreshToken").remove("userId").remove("email").putBoolean("cloudInitialized",false).putBoolean("settingsDirty",false).apply();return"Cloud abgemeldet";}
  String cloudStatus(){if(!cloudConfigured()||p.getString("accessToken","").isEmpty())return"Cloud: nicht angemeldet";R r=cloud("GET",cloudUrl+"/auth/v1/user",null);if(r.code>=200&&r.code<300)try{String email=new JSONObject(r.body).optString("email",p.getString("email",""));if(!email.isEmpty())p.edit().putString("email",email).apply();return"Cloud: angemeldet"+(email.isEmpty()?"":" · "+email);}catch(Exception e){}return"Cloud: nicht angemeldet";}
  void syncProfile(){if(!cloudConfigured()||p.getString("accessToken","").isEmpty())return;try{String id=p.getString("userId","");R r=cloud("GET",cloudUrl+"/rest/v1/jarvis_profiles?id=eq."+URLEncoder.encode(id,"UTF-8")+"&select=*&limit=1",null);JSONArray rows=r.code>=200&&r.code<300?new JSONArray(r.body):new JSONArray();if(rows.length()==0){JSONObject defaults=new JSONObject().put("voice",DEFAULT_VOICE).put("weatherCity",DEFAULT_CITY).put("alwaysOnTop",true).put("wakeEnabled",true);if(p.getBoolean("settingsDirty",false)){defaults.put("voice",p.getString("voice",DEFAULT_VOICE));defaults.put("weatherCity",p.getString("city",DEFAULT_CITY));}if(upsert(id,defaults))p.edit().putBoolean("cloudInitialized",true).putBoolean("settingsDirty",false).apply();return;}JSONObject remote=rows.getJSONObject(0).optJSONObject("settings");if(remote==null)remote=new JSONObject();boolean dirty=p.getBoolean("settingsDirty",false);if(!dirty){SharedPreferences.Editor e=p.edit();if(remote.has("voice"))e.putString("voice",remote.getString("voice"));if(remote.has("weatherCity"))e.putString("city",remote.getString("weatherCity"));if(remote.has("alwaysOnTop"))e.putBoolean("alwaysOnTop",remote.getBoolean("alwaysOnTop"));if(remote.has("wakeEnabled"))e.putBoolean("wakeEnabled",remote.getBoolean("wakeEnabled"));e.putBoolean("cloudInitialized",true).apply();return;}JSONObject merged=new JSONObject(remote.toString());merged.put("voice",p.getString("voice",DEFAULT_VOICE));merged.put("weatherCity",p.getString("city",DEFAULT_CITY));if(upsert(id,merged))p.edit().putBoolean("settingsDirty",false).putBoolean("cloudInitialized",true).apply();}catch(Exception ignored){}}
  private boolean upsert(String id,JSONObject settings){try{Map<String,String>h=cloudHeaders(true);h.put("Prefer","resolution=merge-duplicates,return=minimal");String body=new JSONObject().put("id",id).put("settings",settings).put("updated_at",new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSSXXX",Locale.US).format(new Date())).toString();R r=http("POST",cloudUrl+"/rest/v1/jarvis_profiles",body,h,null,null);if(r.code==401&&!p.getString("refreshToken","").isEmpty()&&refresh().isEmpty())r=http("POST",cloudUrl+"/rest/v1/jarvis_profiles",body,cloudHeaders(true),null,null);return r.code>=200&&r.code<300;}catch(Exception ignored){return false;}}
  String error(R r){try{JSONObject j=new JSONObject(r.body);return j.optString("msg",j.optString("message","Cloud-Fehler ("+r.code+")"));}catch(Exception e){return"Cloud-Fehler ("+r.code+")";}}
}
